import { action } from "solid-js";
const act = () => { void action(function* () {})(); };
const real = Float32Array.prototype.reverse;
document.addEventListener("click", (event) => {
  event.view.Float32Array.prototype.reverse = function () {
    act();
    return real.call(this);
  };
}, { once: true });
document.documentElement.click();
